import React, { useEffect, useState } from 'react';

const StudentDashboard = () => {
    const [studentData, setStudentData] = useState({});
    const [mySubjectsList, setMySubjectsList] = useState([]);

    useEffect(() => {
        // ලොග් වෙද්දී සේව් කරපු ඩේටා ටික LocalStorage එකෙන් ගන්නවා
        const savedData = localStorage.getItem('loggedInStudent');
        
        if (savedData) {
            const parsedData = JSON.parse(savedData);
            setStudentData(parsedData);
            
            // Subjects ටික කොමාවෙන් වෙන් කරලා Array එකක් කරනවා
            if (parsedData.subjects) {
                setMySubjectsList(parsedData.subjects.split(','));
            }
        } else {
            // ඩේටා නැත්නම් ආපහු ලොගින් එකට යවනවා
            window.location.href = '/'; 
        }
    }, []);

    return (
        <div style={{ padding: '30px', fontFamily: 'Arial' }}>
            {/* උඩින්ම ළමයාගේ නම/ID එක පෙන්වනවා */}
            <h2 style={{ color: '#2c3e50' }}>Welcome Back, {studentData.name}! 👋</h2>
            <p style={{ color: '#7f8c8d' }}>Role: {studentData.role}</p>
            
            <hr style={{ margin: '20px 0' }} />
            
            <h3>My Subjects</h3>
            
            {/* විෂයයන් ටික ලස්සනට කාඩ් විදිහට පෙන්වනවා */}
            <div style={{ display: 'flex', gap: '20px', marginTop: '20px', flexWrap: 'wrap' }}>
                {mySubjectsList.length > 0 ? (
                    mySubjectsList.map((subject, index) => (
                        <div key={index} style={{
                            padding: '25px', 
                            border: '1px solid #e0e0e0', 
                            borderRadius: '10px',
                            backgroundColor: '#f8f9fa',
                            minWidth: '180px',
                            textAlign: 'center',
                            boxShadow: '0 4px 8px rgba(0,0,0,0.1)'
                        }}>
                            <h4 style={{ color: '#333', marginBottom: '15px' }}>{subject.trim()}</h4>
                            <button style={{
                                padding: '10px 20px',
                                backgroundColor: '#27ae60',
                                color: 'white',
                                border: 'none',
                                borderRadius: '5px',
                                cursor: 'pointer',
                                width: '100%'
                            }}>
                                Go to Class
                            </button>
                        </div>
                    ))
                ) : (
                    <p>No subjects enrolled yet.</p>
                )}
            </div>
        </div>
    );
};

export default StudentDashboard;
